package affected

import (
	"fmt"
	"io"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

// walks.tsv is GENERATED by `cigate plan-dynreads` from the AST together with dynreads.tsv: one row per walk call
// (filepath.WalkDir/Walk/Glob, os.ReadDir/DirFS, fs.WalkDir/ReadDir/Glob) whose root is a repository directory or cannot
// be bounded:
//
//	package<TAB>site<TAB>root<TAB>depth<TAB>classes
//
// root is the directory the code walks, derived from the AST: a repository-root locator (repoRoot(t), RepoRoot, a go.mod
// lookup) joined with constant ".."-free parts, or a constant path resolved against the package directory. depth is
// `tree` (a recursive walk) or `dir` (os.ReadDir, Glob: one level). classes is what the tracked files under root reach. A
// root the tool cannot derive is `unexpressed` (depth and classes `-`). A walk of a temp dir or of the package's own
// directory needs no row. The planner selects a walker for every changed non-Go path under its root, and for every
// non-Go change when the root is `unexpressed`; the walk's file filter and skipped directories are not modelled, so the
// selection over-approximates and never under-selects. plan-reads fails any difference from the generated rows.
const (
	walkUnexpressed = "unexpressed"
	depthTree       = "tree"
	depthDir        = "dir"
)

type walkRow struct {
	pkg, site, root, depth string
	classes                []string
	line                   int
}

func (w walkRow) scope() string {
	if strings.HasSuffix(w.site, "_test.go") {
		return scopeTest
	}
	return scopeCode
}

func (w walkRow) key() string {
	return w.pkg + "\t" + w.site + "\t" + w.root + "\t" + w.depth
}

func (w walkRow) cells() string {
	c := "-"
	if len(w.classes) > 0 {
		c = strings.Join(w.classes, ",")
	}
	return fmt.Sprintf("%s\t%s\t%s\t%s\t%s", w.pkg, w.site, w.root, w.depth, c)
}

func splitList(v string) []string {
	if v == "-" {
		return nil
	}
	return strings.Split(v, ",")
}

func loadWalks(dir string, known map[string]bool) ([]walkRow, error) {
	rows, lines, err := readTSV(filepath.Join(dir, walksFile), 5)
	if err != nil {
		return nil, err
	}
	var out []walkRow
	for i, r := range rows {
		w := walkRow{pkg: r[0], site: r[1], root: r[2], depth: r[3], classes: splitList(r[4]), line: lines[i]}
		where := fmt.Sprintf("%s:%d", walksFile, w.line)
		if path.Clean(w.pkg) != w.pkg || strings.HasPrefix(w.pkg, "/") || strings.HasPrefix(w.pkg, "../") {
			return nil, fmt.Errorf("%s: package %q is not a clean repository path", where, w.pkg)
		}
		if !strings.HasSuffix(w.site, ".go") || strings.Contains(w.site, "/") {
			return nil, fmt.Errorf("%s: site %q is not a Go file base name", where, w.site)
		}
		switch {
		case w.root == walkUnexpressed:
			if w.depth != "-" {
				return nil, fmt.Errorf("%s: an unexpressed root has depth `-`", where)
			}
		case w.root != "." && (path.Clean(w.root) != w.root || strings.HasPrefix(w.root, "/") || strings.HasPrefix(w.root, "../")):
			return nil, fmt.Errorf("%s: root %q is not `.`, a clean repository directory or %s", where, w.root, walkUnexpressed)
		case w.depth != depthTree && w.depth != depthDir:
			return nil, fmt.Errorf("%s: depth %q is neither %s nor %s", where, w.depth, depthTree, depthDir)
		}
		for _, c := range w.classes {
			if !known[c] {
				return nil, fmt.Errorf("%s: class %q is not in %s", where, c, classesFile)
			}
		}
		out = append(out, w)
	}
	return out, nil
}

// matches reports whether the walk can read repository path p.
func (w walkRow) matches(p string) bool {
	if w.root == walkUnexpressed {
		return true
	}
	rel := p
	if w.root != "." {
		if !strings.HasPrefix(p, w.root+"/") {
			return false
		}
		rel = p[len(w.root)+1:]
	}
	return w.depth == depthTree || !strings.Contains(rel, "/")
}

// reachOf is the classes of the tracked files the walk can read; only known (anchored) paths count, since a change
// anywhere else plans FULL.
func (t *tables) reachOf(files []string, w walkRow) []string {
	got := map[string]bool{}
	for _, f := range files {
		if !w.matches(f) {
			continue
		}
		if classes, known := t.classesOf(f); known {
			for c := range classes {
				got[c] = true
			}
		}
	}
	return sortedKeys(got)
}

// walkersOf is every walk row that reads p.
func (t *tables) walkersOf(p string) []walkRow {
	var out []walkRow
	for _, w := range t.walks {
		if w.matches(p) {
			out = append(out, w)
		}
	}
	return out
}

// walkDiff compares the checked-in walks.tsv with the generated rows: one line per difference.
func walkDiff(generated []walkRow, samples map[string]string, t *tables) []string {
	have := map[string]walkRow{}
	for _, w := range t.walks {
		have[w.key()] = w
	}
	var out []string
	for _, g := range generated {
		h, ok := have[g.key()]
		delete(have, g.key())
		switch {
		case !ok:
			out = append(out, fmt.Sprintf("%s: undeclared walk: %s; the generated row is %s (cigate plan-dynreads)", g.pkg, samples[g.key()], g.cells()))
		case h.cells() != g.cells():
			out = append(out, fmt.Sprintf("%s:%d: %s, the generated row is %s (%s)", walksFile, h.line, h.cells(), g.cells(), samples[g.key()]))
		}
	}
	for _, h := range have {
		out = append(out, fmt.Sprintf("%s:%d: %s matches no walk in the code (no generated %s/%s walk of root %s)", walksFile, h.line, h.cells(), h.pkg, h.site, h.root))
	}
	sort.Strings(out)
	return out
}

// logRootWalks writes, for every walking package, the classes its walks reach against the classes the change reaches,
// and whether the change selected it: a false NONE that rests on a walk shows in the job log.
func (t *tables) logRootWalks(w io.Writer, reached map[string]bool, selected map[string]bool) {
	if w == nil || len(reached) == 0 {
		return
	}
	declared := map[string]map[string]bool{}
	for _, r := range t.walks {
		if declared[r.pkg] == nil {
			declared[r.pkg] = map[string]bool{}
		}
		for _, c := range r.classes {
			declared[r.pkg][c] = true
		}
		if r.root == walkUnexpressed {
			declared[r.pkg][walkUnexpressed] = true
		}
	}
	reach := sortedKeys(reached)
	var pkgs []string
	for p := range declared {
		pkgs = append(pkgs, p)
	}
	sort.Strings(pkgs)
	for _, p := range pkgs {
		state := "not selected"
		if selected[p] {
			state = "selected"
		}
		fmt.Fprintf(w, "root walk in %s: classes declared %v, reachable %v; %s\n", p, sortedKeys(declared[p]), reach, state)
	}
}

func sortedKeys(m map[string]bool) []string {
	out := []string{}
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}
